svg.script:
(async () => {
  const status = document.getElementById("status");
  // ?boot marks the reload. If the worker still has not answered that, say so
  // rather than reloading forever (and drop the mark, so a reload retries).
  const url = new URL(location.href);
  try {
    if (!("serviceWorker" in navigator)) throw new Error("This browser has no service worker support.");
    if (url.searchParams.has("boot")) throw new Error("Roblox couldn't start here. Reload to try again.");
    await navigator.serviceWorker.register(new URL("sw.js?standalone", location.href), { scope: "./" });
    await navigator.serviceWorker.ready;
    url.searchParams.set("boot", "");
    location.replace(url);
  } catch (error) {
    url.searchParams.delete("boot");
    history.replaceState(history.state, "", url);
    status.textContent = error.message || String(error);
  }
})();
